mapper.select:
SELECT * FROM website_visit
WHERE ip = #{ip}
  AND visit_date = #{visitDate}

SELECT * FROM website_visit
ORDER BY last_visit_time DESC
LIMIT #{limit}

mapper.update:
UPDATE website_visit
SET count = count + 1,
    last_visit_time = #{time}
WHERE id = #{id}

UPDATE website_visit
SET user_id = #{userId}
WHERE id = #{id}
